import json
with open('results/h100_grokking_race/wiring_check.json') as f:
    d = json.load(f)
# find muon/mamba and muon/vit and muon/decoder entries
def find(obj, path=''):
    results=[]
    if isinstance(obj, dict):
        for k,v in obj.items():
            results += find(v, path+'/'+str(k))
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            results += find(v, path+'['+str(i)+']')
    else:
        s=str(obj)
        if 'muon' in s.lower() and ('mamba' in s.lower() or 'NS' in s or 'grid-cooperative' in s.lower() or '2D weight' in s):
            results.append((path, s))
    return results
for p,s in find(d):
    print(p, '=>', s[:400])
    print('---')
