722	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
723	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
724	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
725	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
726	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
727	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
728	// nCTA (the dW/embedding owner maps are functions of nCTA).
729	template <OptId Opt>
730	cudaError_t launch_fused_decoder_megakernel_tc(
731	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
732	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
733	        int ncta_cap = 0) {
734	    int dev = 0;
735	    cudaError_t err = cudaGetDevice(&dev);
736	    if (err != cudaSuccess) return err;
737	    int n_sms = 0;
738	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
739	    if (err != cudaSuccess) return err;

125	
126	    // Bind the optimizer state slices. [m | v | extra] over the SAME state buffer;
127	    // each tail reads only its own buffers (opt_components.cuh guarantees unused
128	    // pointers are never dereferenced). ema/psi-net live in the `extra` slice.
129	    float* const extra_slice = state + 2 * total;
130	    FusedOptState st;
131	    st.exp_avg    = state;
132	    st.exp_avg_sq = state + total;
133	    st.ema        = extra_slice;          // grokfast/grokadamw slow-grad EMA
134	    st.psi_W1     = extra_slice + kPsiW1Off;   // neuralgrok psi-net pack (when wired)
135	    st.psi_b1     = extra_slice + kPsiB1Off;
136	    st.psi_W2     = extra_slice + kPsiW2Off;
137	    // PRODIGY (STAGED global-d) state bindings (mirror the decoder/vit TC launchers).
138	    // The cell extends the state buffer to [m | v | extra/s_track | loss | param_init |
139	    // r_ema | s_ema | d_lr] (host sizes it >= 4*total+4; dispatch.fused_train_step). The
140	    // `extra` slice doubles as Prodigy's `s` trajectory accumulator (the apply reads
141	    // st.s_track, not st.ema — they alias here, harmless: Prodigy has no slow-grad EMA).
142	    // loss_out == dispatch's loss_slot (state+3*total), so param_init = loss_out+1 and
143	    // the 3 persisted estimator scalars [r_ema | s_ema | d_lr] follow param_init.
144	    st.s_track        = extra_slice;            // Prodigy `s` (per-element accumulator)
145	    st.param_init     = loss_out + 1;           // state + 3*total + 1
146	    st.prodigy_persist = loss_out + 1 + total;  // [r_ema | s_ema | d_lr]
147	    apply_scalars(st, scalars);   // FULL scalar set (un-frozen bc1/bc2/... + d0/d_coef/beta3)
148	    st.lr = lr;
149	
150	    MambaTokenCtx tok;
151	    tok.tokens    = tokens;
152	    tok.targets   = targets;
153	    tok.B         = B;
154	    tok.workspace = sc.workspace;
155	    tok.loss_out  = loss_out;
156	
157	    // Dispatch to the matching kernel instantiation. The fwd+bwd is identical across
158	    // these OptIds; the template differs ONLY in the P3 apply_optimizer<Opt> tail.
159	    // Unsupported opt_ids return cudaErrorInvalidValue → dispatch.cpp throws LOUD.
160	    switch (static_cast<OptId>(opt_id)) {
161	        case OptId::AdamW:
162	            return launch_fused_mamba_megakernel_tc<OptId::AdamW>(
163	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
164	        case OptId::Lion:
165	            return launch_fused_mamba_megakernel_tc<OptId::Lion>(
166	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
167	        case OptId::Grokfast:
168	            return launch_fused_mamba_megakernel_tc<OptId::Grokfast>(
169	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
170	        case OptId::GrokAdamW:
171	            // 3-mechanism GrokAdamW (wave-2 mamba): the kernel's P2.5 global grad-norm
172	            // clip + P3 per-tensor layer-wise β1 land in fused_mamba_megakernel_tc<Opt>
173	            // (mirrors the decoder/vit TC kernels). γ/grad_clip thread through
174	            // FusedScalars (apply_scalars). ema = the `extra` slice (cold-start seed).
175	            return launch_fused_mamba_megakernel_tc<OptId::GrokAdamW>(
176	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
177	        case OptId::NeuralGrok:
178	            // psi-net MLP tail (wave-2 mamba): apply_optimizer<NeuralGrok> reads the
179	            // psi pack the host scattered into the `extra` slice (st.psi_W1/b1/W2 bound
180	            // above) + alpha/beta from FusedScalars. Pure elementwise — no precompute,
181	            // no cross-CTA reduction, so it inherits the deterministic grad reduce.
182	            return launch_fused_mamba_megakernel_tc<OptId::NeuralGrok>(
183	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
184	        case OptId::Prodigy:
185	            // STAGED global-d (wave-2 mamba): the SAME single persistent launch — the
186	            // cross-ALL-tensors d-estimate is an IN-KERNEL phase (P2.6, between the grad
187	            // reduce B2 and the apply P3), not a separate launch. st carries param_init/
188	            // prodigy_persist/d0/d_coef/beta3 (bound above); the mamba TC kernel decays+
189	            // accumulates the EMA, updates d, applies. The reduce slots are carved in
190	            // mb_tc_workspace_floats (mb_tc_opt_reduce_floats), so this scratch already fits.
191	            return launch_fused_mamba_megakernel_tc<OptId::Prodigy>(
192	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
193	        default:
194	            return cudaErrorInvalidValue;  // STAGED/coupled opt not single-launch TC
195	    }
196	}
