391	// dW split-K partial floats (0 when G==1 → no extra scratch, the single-CTA path).
392	__host__ __device__ __forceinline__ int64_t mb_tc_dw_part_floats() {
393	    return (mbtc::kMbDwSplitK > 1) ? mbtc::mb_dw_part_floats(mbtc::kMbDwSplitK) : 0;
394	}
395	// STAGED-optimizer cross-CTA reduction scratch (Prodigy d-estimate). Mirrors the
396	// decoder's dec_tc_opt_reduce_floats: the Prodigy P2.6 stage publishes per-CTA (r,s)
397	// slots (2*nCTA) + a reduced-d broadcast slot (1) — an owner-computes tree
398	// (opt_stages_precompute.cuh), NO float atomic. Sized for the LARGEST nCTA (one
399	// CTA/SM = #SMs); tiny (≤ 2*132+1 ≈ 1 KB) and carved UNCONDITIONALLY so the opt-
400	// agnostic cached launcher workspace fits every OptId. Unused by AdamW/Lion/… (their
401	// P3 never touches this region), so adding it leaves those cells byte-identical.
402	__host__ __device__ __forceinline__ int64_t mb_tc_opt_reduce_floats(int nCTA) {
403	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
404	}
405	__host__ __device__ __forceinline__ int64_t mb_tc_workspace_floats(int T, int nCTA) {
406	    return mb_tc_acts_floats(T)
407	         + (int64_t)nCTA * mbtc::mb_tile_scratch_floats()
408	         + (int64_t)nCTA * mbtc::kPartElems
409	         + nCTA + 1
410	         + mb_tc_dw_part_floats()                       // split-K dW partials (G>1)
411	         + mb_tc_opt_reduce_floats(nCTA)                // STAGED-opt (Prodigy) reduce slots
412	#if SG_MB_TC_PROFILE
413	         + (int64_t)nCTA * SG_MBTC_PROF_SLOTS * 2 + 2  // phase-profiler (doubles=2 floats) + align pad
414	#endif
415	         ;
416	}
