418	template <OptId Opt>
419	__global__ void SG_MBTC_LAUNCH_BOUNDS
420	fused_mamba_megakernel_tc(PersistentContext ctx,
421	                          float* __restrict__ params,
422	                          MambaTokenCtx tok,
423	                          float* __restrict__ grad,
424	                          float lr, int step, FusedOptState st) {
425	    __shared__ MbTcSmem sm;
426	    GridBarrier bar = ctx.barrier();
427	    const int cta = blockIdx.x;
428	    const int nCTA = (int)ctx.n_ctas;
429	    const int B = tok.B;
430	    const int T = B * mb::kSeq;
431	
432	    // Workspace partition.
433	    float* ws = tok.workspace;
434	    const int64_t acts_f = mb_tc_acts_floats(T);
435	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
436	    float* scratch_base = ws + acts_f;
437	    const int64_t scratch_per = mbtc::mb_tile_scratch_floats();
438	    float* part_base = scratch_base + (int64_t)nCTA * scratch_per;
439	    float* loss_part = part_base + (int64_t)nCTA * mbtc::kPartElems;
440	    float* loss_out  = loss_part + nCTA;
441	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
442	    // loss slot (matches mb_tc_workspace_floats's term order). G==1 → dw_part unused.
443	    float* dw_part   = loss_out + 1;
444	    const int kDwG   = mbtc::kMbDwSplitK;
445	    // STAGED-opt (Prodigy P2.6) cross-CTA reduce slots: [r slots | s slots | reduced d]
446	    // = 2*nCTA+1, carved AFTER the split-K dW partials (matches mb_tc_workspace_floats's
447	    // term order). Unused by every non-Prodigy tail (their P3 never touches it), so this
448	    // pointer derivation leaves those cells byte-identical.
449	    float* opt_reduce = dw_part + mb_tc_dw_part_floats();
450	#if SG_MB_TC_PROFILE
