706	cudaError_t launch_fused_mamba_megakernel_tc(
707	        PersistentContext ctx, float* params, MambaTokenCtx tok,
708	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
709	        int ncta_cap = 0) {
710	    int dev = 0;
711	    cudaError_t err = cudaGetDevice(&dev);
712	    if (err != cudaSuccess) return err;
713	    int n_sms = 0;
714	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
715	    if (err != cudaSuccess) return err;
716	
717	    int occ = 0;
718	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
719	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK,
720	        /*dynamicSMemBytes=*/0);
721	    if (err != cudaSuccess) return err;
722	    if (occ < 1) return cudaErrorLaunchOutOfResources;
723	
724	    // OCCUPANCY-FILL: at min-blocks≥2 the kernel is built ≤128 reg/thread so `occ`
725	    // CTAs co-reside per SM. Launch occ·n_sms CTAs (one full residency set) so the
726	    // co-resident CTAs hide each other's HBM latency across the scan/conv/LN phases
727	    // that run fully exposed at occ=1 — the persistent grid barrier rendezvous is
728	    // over the LAUNCHED count and occ·n_sms are guaranteed simultaneously resident,
729	    // so it stays hang-free. Determinism is per fixed launched nCTA (ascending-CTA
730	    // reduce). At min-blocks==1 (shipped default) occ==1 → identical to before.
731	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
732	    unsigned launch_ctas = (unsigned)n_sms * waves;
733	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
734	    ctx.n_ctas = launch_ctas;
735	    // B%16: the dW K-loop contracts K=T=B·8 in 16-step atoms. It ALSO guarantees
736	    // FULL tiles (T%kTileM==0 for kTileM∈{64,128}), which the projection GEMMs
737	    // REQUIRE — they process a compile-time M-extent of kTileM rows (kAtomsM
738	    // atoms), NOT the runtime `nrows`; a partial final tile would feed garbage
739	    // pad rows to the wgmma while the scalar scan/conv loops process only nsamp.
740	    // (A future relaxation to B%2 would satisfy the K-atom reason but silently
741	    // break partial tiles — keep B%16.)
742	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
743	    // SPLIT-K dW (G>1) needs equal 16-aligned K-chunks: G must divide k_steps_total
744	    // = T/16 = B·kSeq/16 = B/2 (kSeq=8). With B%16==0, B/2%4==0, so G∈{1,2,4} are
745	    // always legal; a larger/odd G that doesn't divide B/2 would silently DROP the
746	    // remainder k-steps from every dW (a correctness bug) — REFUSE loudly instead.
747	    if (mbtc::kMbDwSplitK > 1 && (((int64_t)tok.B * mb::kSeq / wgs::kWgmmaAtomK) % mbtc::kMbDwSplitK) != 0)
